#include <LiquidCrystal.h>

// =============================
// Pin Definitions
// =============================

// Ultrasonic sensor
const int trigPin = 12;
const int echoPin = 13;

// IR sensor
const int irPin = 2;

// Relay / Pump
const int pumpPin = 11;

// LCD: RS, E, D4, D5, D6, D7
LiquidCrystal lcd(A0, A1, A2, A3, A4, A5);

// Variables
long duration;
int distance;


void setup()
{
  // Serial monitor
    Serial.begin(9600);

      // Sensor pins
        pinMode(trigPin, OUTPUT);
          pinMode(echoPin, INPUT);
            pinMode(irPin, INPUT);

              // Pump
                pinMode(pumpPin, OUTPUT);
                  digitalWrite(pumpPin, LOW);

                    // LCD
                      lcd.begin(16, 2);

                        // First line
                          lcd.setCursor(0, 0);
                            lcd.print("Reg: 24BCE8046");

                              // Second line
                                lcd.setCursor(0, 1);
                                  lcd.print("Name: U Hari");
                                  }


                                  void loop()
                                  {
                                    // Read IR sensor
                                      int IR = digitalRead(irPin);

                                        // ==================================
                                          // GLASS DETECTED
                                            // ==================================

                                              if (IR == HIGH)
                                                {
                                                    Serial.println("Glass Available");

                                                        // -----------------------------
                                                            // Ultrasonic measurement
                                                                // -----------------------------

                                                                    digitalWrite(trigPin, LOW);
                                                                        delayMicroseconds(2);

                                                                            digitalWrite(trigPin, HIGH);
                                                                                delayMicroseconds(10);

                                                                                    digitalWrite(trigPin, LOW);

                                                                                        // Read echo
                                                                                            duration = pulseIn(echoPin, HIGH, 30000);

                                                                                                // If no echo
                                                                                                    if (duration == 0)
                                                                                                        {
                                                                                                              Serial.println("No Ultrasonic Echo");

                                                                                                                    digitalWrite(pumpPin, LOW);
                                                                                                                        }
                                                                                                                            else
                                                                                                                                {
                                                                                                                                      // Calculate distance in cm
                                                                                                                                            distance = duration * 0.034 / 2;

                                                                                                                                                  Serial.print("Distance: ");
                                                                                                                                                        Serial.print(distance);
                                                                                                                                                              Serial.println(" cm");

                                                                                                                                                                    // Original calculation
                                                                                                                                                                          int D = map(distance, 10, 1095, 0, 400);

                                                                                                                                                                                // -----------------------------
                                                                                                                                                                                      // Pump control
                                                                                                                                                                                            // -----------------------------

                                                                                                                                                                                                  if (D < 200)
                                                                                                                                                                                                        {
                                                                                                                                                                                                                Serial.println("Pump: Start");

                                                                                                                                                                                                                        digitalWrite(pumpPin, HIGH);
                                                                                                                                                                                                                              }
                                                                                                                                                                                                                                    else
                                                                                                                                                                                                                                          {
                                                                                                                                                                                                                                                  Serial.println("Glass: Full");

                                                                                                                                                                                                                                                          digitalWrite(pumpPin, LOW);
                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                        // ==================================
                                                                                                                                                                                                                                                                          // NO GLASS
                                                                                                                                                                                                                                                                            // ==================================

                                                                                                                                                                                                                                                                              else
                                                                                                                                                                                                                                                                                {
                                                                                                                                                                                                                                                                                    Serial.println("No Glass");

                                                                                                                                                                                                                                                                                        // Turn pump OFF
                                                                                                                                                                                                                                                                                            digitalWrite(pumpPin, LOW);
                                                                                                                                                                                                                                                                                              }

                                                                                                                                                                                                                                                                                                delay(100);
                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                ```
